def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for fail in failed:
        self.handle_failed_request(fail)
    if not self.running:
        return False
    return True

def handle_failed_request(self, fail):
    error_message = f'Request failed: {fail}'
    print(error_message)

def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for handle in failed:
        handle.request.handle_result()
        self.emit('REST-failed', handle.request.id, handle.request)
    if not self.running:
        return False
    return True

def _query(self, query):
    old = query.copy()
    self.pre_translation(query)
    if old != query:
        log.debug('RHBugzilla altered query to: %s', query)
    ret = self._proxy.Bug.search(query)
    if self._is_older_rhbz():
        for bug in ret['bugs']:
            self.post_translation(query, bug)
    return ret

def _is_older_rhbz(self):
    return False

def _make_datetime_field_compatible(self, field):
    if isinstance(field, datetime):
        if isinstance(field.tzinfo, tzlocal) and (not hasattr(field.tzinfo, '_hasdst')):
            logger.info('Python-dateutil logs: Making datetime field compatible to python-dateutil package')
            return datetime(year=field.year, month=field.month, day=field.day, hour=field.hour, minute=field.minute, second=field.second, tzinfo=tzlocal())
    return field

