def get_table_resize(table_data, table_col_count, page_width, average_column_width) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        if table_col_count * average_column_width > page_width:
            resize = True
    return resize

def get_table_resize(table_data, table_col_count) -> bool:
    resize = False
    page_width = 800
    total_column_width = 0
    try:
        resize = table_data['fitToPageWidth']
    except:
        for i in range(table_col_count):
            column_width = parse_size_attribute(table_data['columns'][i]['width'])
            total_column_width += column_width
        if total_column_width > page_width:
            resize = True
    return resize

