def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    result = []
    for part in repo.working_copy.parts:
        table_wc = part.tabular
        table_wc_path = table_wc.clean_location if table_wc else None
        result.append({'path': table_wc_path, 'changes': get_diff_status_json(part)})
    return result

def get_working_copy_status_json(repo):
    if repo.is_bare:
        return None
    working_copies = repo.working_copy.parts
    results = []
    for wc in working_copies:
        table_wc_path = wc.tabular.clean_location if wc.tabular else None
        result = {'path': table_wc_path, 'changes': get_diff_status_json(repo)}
        results.append(result)
    return results

import nntplib
