def connect(self):
    log.info('Attempting to connect to news server...')
    ssl = config.news.pop('ssl', False)
    use_compression = config.news.pop('compression', False)
    try:
        if ssl:
            self.connection = nntplib.NNTP_SSL(**config.news)
        else:
            self.connection = nntplib.NNTP(**config.news)
        if use_compression:
            self.connection.enable_compression()
    except Exception as e:
        log.error('Could not connect to news server: ' + str(e))
        return False
    log.info('Connected!')
    return True

def connect(self):
    log.info('Attempting to connect to news server...')
    ssl = config.news.pop('ssl', False)
    compression = config.news.pop('compression', False)
    try:
        if ssl:
            self.connection = nntplib.NNTP_SSL(**config.news)
        else:
            self.connection = nntplib.NNTP(**config.news)
        if compression:
            log.info('Compression enabled for the connection.')
        else:
            log.warning('Compression is not enabled for the connection.')
