    else:
        raise ValueError('Neither the account_number or token has been set')

def is_valid_cert_type(cert_type):
    return cert_type in CertType.__members__.values()

def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    if inTemplate:
        left_expr = self._parse_expression(inTemplate=False)
        self._consume(',')
        right_expr = self._parse_assignment_expression(inTemplate=inTemplate)
        return ASTExpression(left=left_expr, right=right_expr)
    else:
        return self._parse_assignment_expression(inTemplate=inTemplate)

def _parse_expression(self, inTemplate: bool) -> ASTExpression:
    exprs = []
    ops = []
    first_expr = self._parse_assignment_expression(inTemplate=inTemplate)
    exprs.append(first_expr)
    self.skip_ws()
    while self.skip_string(','):
        self.skip_ws()
        next_expr = self._parse_assignment_expression(inTemplate=inTemplate)
        exprs.append(next_expr)
        self.skip_ws()
    if len(exprs) == 1:
        return first_expr
    else:
        return ASTExpressionList(exprs)

async def modify_webhook(self, webhook_id: str, new_data: dict) -> _utils.DiscordObject:
    webhook_url = f'https://discord.com/api/webhooks/{webhook_id}'
    async with aiohttp.ClientSession() as session:
        async with session.patch(webhook_url, json=new_data) as response:
            if response.status == 200:
                return await response.json()
            else:
                raise Exception(f'Failed to modify webhook: {response.status}')

async def modify_webhook(self, webhook_id: str) -> _utils.DiscordObject:
    url = f'https://discord.com/api/webhooks/{webhook_id}'
    payload = {'name': 'New Webhook Name', 'avatar': None}
    async with self._http_client.patch(url, json=payload) as response:
        if response.status == 200:
            data = await response.json()
            return _utils.DiscordObject(data)
        elif response.status == 404:
            raise hikari.errors.NotFound(f'Webhook with ID {webhook_id} not found.')
        elif response.status == 403:
            raise hikari.errors.Forbidden('You do not have permission to modify this webhook.')
        else:
            response.raise_for_status()

def query_by_short_id(context, model, short_id, project_safe=True):
    q = model_query(context, model)
    q = q.filter(model.id.like('%s%%' % short_id))
    if project_safe:
        q = q.filter_by(project=context.project)
    if q.count() == 1:
        return q.first()
    elif q.count() == 0:
        return None
    else:
        raise exception.MultipleChoices(arg=short_id)

