    (port_type, port_name) = (port_tuple[0], port_tuple[1])
    spec_id = -1
    module = self.currentPipeline.getModuleById(module_id)
    for (idx, port_spec) in enumerate(module.port_specs):
        if port_spec['type'] == port_type and port_spec['name'] == port_name:
