    if online_webcasts:
        data['message_data']['webcast'] = online_webcasts[0]
    else:
        data['message_data']['webcast'] = None
    return data

def isSpreadSheetCell(self, obj, startFromTable=False):
    cell = obj
    if not startFromTable:
        obj = obj.parent
    while obj:
        if obj.queryTable():
            break
        obj = obj.parent
    if obj is None:
        return False
    try:
        table = obj.queryTable()
        return table.nRows in [65536, 1048576]
    except Exception as e:
        return False

def isSpreadSheetCell(self, obj, startFromTable=False):
    if not startFromTable:
        obj = obj.parent
    try:
        table = obj.queryTable()
    except:
        return False
    else:
        return table.nRows in [65536, 1048576]

def do_main():
    from xpra.os_util import SIGNAMES
    from xpra.scripts.main import InitExit, InitInfo
    from xpra.gtk_common.quit import gtk_main_quit_on_fatal_exceptions_enable
    gtk_main_quit_on_fatal_exceptions_enable()
    from xpra.platform.gui import ready as gui_ready
    gui_init()
    try:
        from xpra.scripts.parsing import parse_cmdline, fixup_debug_option
        (options, args) = parse_cmdline(sys.argv)
        debug = fixup_debug_option(options.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
    except InitInfo as e:
        print(str(e))
        return 0
    except InitExit as e:
        return e.status
    except Exception:
        exception_dialog('Error parsing command line')
        return 1
    from xpra.scripts import config
    config.debug = log.debug
    try:
        app = ApplicationWindow()

        def app_signal(signum, _frame):
            print('')
            log('got signal %s' % SIGNAMES.get(signum, signum))

            def show_signal():
                app.show()
                app.client.cleanup()
                glib.timeout_add(1000, app.set_info_text, 'got signal %s' % SIGNAMES.get(signum, signum))
                glib.timeout_add(1000, app.set_info_color, True)
            glib.idle_add(show_signal)
        if sys.version_info[0] < 3:
            signal.signal(signal.SIGINT, app_signal)
        signal.signal(signal.SIGTERM, app_signal)
        has_file = len(args) == 1
        if has_file:
            app.update_options_from_file(args[0])
            configure_network(app.config)
        debug = fixup_debug_option(app.config.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
        app.create_window_with_config()
    except Exception:
        exception_dialog('Error creating launcher form')
        return 1

    def setup_file_and_url_handlers():
        if app.config.autoconnect:
            glib.idle_add(app.do_connect)
        if not has_file:
            app.reset_errors()
        gui_ready()
        if not app.config.autoconnect or app.config.debug:
            if OSX:

                def force_show():
                    from xpra.platform.darwin.gui import enable_focus_workaround, disable_focus_workaround
                    enable_focus_workaround()
                    app.show()
                    glib.timeout_add(500, disable_focus_workaround)
                app.__osx_open_signal = False

                def do_open_file(filename):
                    log.info('do_open_file(%s)', filename)
                    app.update_options_from_file(filename)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    if app.config.autoconnect:
                        app.__osx_open_signal = True
                        glib.idle_add(app.do_connect)
                    else:
                        force_show()

                def open_file(_, filename):
                    log.info('open_file(%s)', filename)
                    glib.idle_add(do_open_file, filename)

                def do_open_URL(url):
                    log.info('do_open_URL(%s)', url)
                    app.__osx_open_signal = True
                    app.update_options_from_URL(url)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    glib.idle_add(app.do_connect)

                def open_URL(url):
                    log.info('open_URL(%s)', url)
                    glib.idle_add(do_open_URL, url)
                from xpra.platform.darwin.gui import get_OSXApplication, register_URL_handler
                register_URL_handler(open_URL)
                try:
                    get_OSXApplication().connect('NSApplicationOpenFile', open_file)
                except Exception as e:
                    log.error('Error: cannot handle file associations:')
                    log.error(' %s', e)

                def may_show():
                    log('may_show() osx open signal=%s', app.__osx_open_signal)
                    if not app.__osx_open_signal:
                        force_show()
                glib.timeout_add(500, may_show)
            else:
                app.show()
    setup_file_and_url_handlers()
    app.run()
    return 0

def do_main():
    from xpra.os_util import SIGNAMES
    from xpra.scripts.main import InitExit, InitInfo
    from xpra.gtk_common.quit import gtk_main_quit_on_fatal_exceptions_enable
    gtk_main_quit_on_fatal_exceptions_enable()
    from xpra.platform.gui import ready as gui_ready
    gui_init()
    try:
        from xpra.scripts.parsing import parse_cmdline, fixup_debug_option
        (options, args) = parse_cmdline(sys.argv)
        debug = fixup_debug_option(options.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
    except InitInfo as e:
        print(str(e))
        return 0
    except InitExit as e:
        return e.status
    except Exception:
        exception_dialog('Error parsing command line')
        return 1
    from xpra.scripts import config
    config.debug = log.debug
    try:
        app = ApplicationWindow()

        def app_signal(signum, _frame):
            print('')
            log('got signal %s' % SIGNAMES.get(signum, signum))

            def show_signal():
                app.show()
                app.client.cleanup()
                glib.timeout_add(1000, app.set_info_text, 'got signal %s' % SIGNAMES.get(signum, signum))
                glib.timeout_add(1000, app.set_info_color, True)
            glib.idle_add(show_signal)
        if sys.version_info[0] < 3:
            signal.signal(signal.SIGINT, app_signal)
        signal.signal(signal.SIGTERM, app_signal)
        has_file = len(args) == 1
        if has_file:
            app.update_options_from_file(args[0])
            configure_network(app.config)
        debug = fixup_debug_option(app.config.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
        app.create_window_with_config()
    except Exception:
        exception_dialog('Error creating launcher form')
        return 1
    try:
        if app.config.autoconnect:
            glib.idle_add(app.do_connect)
        if not has_file:
            app.reset_errors()
        gui_ready()
        if not app.config.autoconnect or app.config.debug:
            if OSX:

                def force_show():
                    from xpra.platform.darwin.gui import enable_focus_workaround, disable_focus_workaround
                    enable_focus_workaround()
                    app.show()
                    glib.timeout_add(500, disable_focus_workaround)
                app.__osx_open_signal = False

                def do_open_file(filename):
                    log.info('do_open_file(%s)', filename)
                    app.update_options_from_file(filename)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    if app.config.autoconnect:
                        app.__osx_open_signal = True
                        glib.idle_add(app.do_connect)
                    else:
                        force_show()

                def open_file(_, filename):
                    log.info('open_file(%s)', filename)
                    glib.idle_add(do_open_file, filename)

                def do_open_URL(url):
                    log.info('do_open_URL(%s)', url)
                    app.__osx_open_signal = True
                    app.update_options_from_URL(url)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    glib.idle_add(app.do_connect)

                def open_URL(url):
                    log.info('open_URL(%s)', url)
                    glib.idle_add(do_open_URL, url)
                from xpra.platform.darwin.gui import get_OSXApplication, register_URL_handler
                register_URL_handler(open_URL)
                try:
                    get_OSXApplication().connect('NSApplicationOpenFile', open_file)
                except Exception as e:
                    log.error('Error: cannot handle file associations:')
                    log.error(' %s', e)

                def may_show():
                    log('may_show() osx open signal=%s', app.__osx_open_signal)
                    if not app.__osx_open_signal:
                        force_show()
                glib.timeout_add(500, may_show)
            else:
                app.show()
        app.run()
    except KeyboardInterrupt:
        pass
    return 0

def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                try:
                    response = requests.get(tryfn)
                    if response.status_code != 200:
                        py.test.fail('Failed to retrieve %r: Status code %d in %s:%d' % (tryfn, response.status_code, path.basename, lineno + 1))
                except Exception as e:
                    py.test.fail('Error retrieving %r: %s in %s:%d' % (tryfn, str(e), path.basename, lineno + 1))
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            else:
                pass

import requests

def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                try:
                    response = requests.get(tryfn)
                    response.raise_for_status()
                except requests.exceptions.RequestException as e:
                    py.test.fail(f'Failed to retrieve {tryfn}: {e}')
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d ' % (tryfn, path.basename, lineno + 1))
            else:
                pass

import codecs

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if 'Content-Type' in info_dict:
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode = ct_line[csi + 9:]
                try:
                    codecs.lookup(encode)
                except LookupError:
                    encode = 'utf-8'
        uopener.close()
        self.urlOpener.close()
    except IOError as e:
        raise IMDbDataAccessError({'errcode': e.errno, 'errmsg': str(e.strerror), 'url': url, 'proxy': self.get_proxy()})
    return content.decode(encode, 'replace')

import codecs

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if 'Content-Type' in info_dict:
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                charset = ct_line[csi + 9:]
                try:
                    codecs.lookup(charset)
                    encode = charset
                except LookupError:
                    pass
        uopener.close()
        self.urlOpener.close()
    except IOError as e:
        raise IMDbDataAccessError({'errcode': e.errno, 'errmsg': str(e.strerror), 'url': url, 'proxy': self.get_proxy()})
    return content.decode(encode, 'replace')

import os
import click
from wandb import Config

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        if os.path.isfile(config_path):
            raise Exception('Migration of existing configuration files is required. Please handle this manually.')
        os.mkdir(config_path)
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

import os
import click
from wandb import Config

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        if os.path.isfile(config_path):
            raise Exception('Configuration path exists as a file. Please remove it before initializing.')
        os.mkdir(config_path)
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

def get_owned_blocks(self, user_id: int) -> Dict[int, BlockAccess]:
    INVALID_BLOCK_ID = -1
    return self.get_accessible_blocks(user_id, [INVALID_BLOCK_ID])

import os
import urllib.parse

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    if not os.path.isfile(urls_file):
        raise FileNotFoundError(f'The file {urls_file} does not exist.')
    with open(urls_file, 'r') as file:
        for line in file:
            url = line.strip()
            if not url:
                continue
            parsed_url = urllib.parse.urlparse(url)
            if not all([parsed_url.scheme, parsed_url.netloc]):
                print(f'Invalid URL: {url}')
                continue
            collect_from_url(url, archive_dir=archive_dir, notes=notes)

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    try:
        with open(urls_file, 'r') as file:
            for line in file:
                url = line.strip()
                if url:
                    collect_from_url(url, archive_dir=archive_dir, notes=notes)
                else:
                    print('Warning: Empty line found in URLs file.')
    except FileNotFoundError:
        print(f'Error: The file {urls_file} was not found.')
    except Exception as e:
        print(f'An error occurred: {e}')

def finish_song_deletion(self, coresong):

    def update_cb(conn, res):
        if res is None or not res.success:
            self._log.error('Failed to update the database.')
            self._notificationmanager.pop_loading()
            return
        conn.update_finish(res)
        self._notificationmanager.pop_loading()

    def entry_retrieved_cb(source, op_id, media, remaining, error):
        if error:
            self._log.warning('Error: {}'.format(error))
            return
        if not media:
            return
        self._notificationmanager.push_loading()
        update_query = '
        INSERT OR REPLACE {
            ?entry nfo:listPosition ?position .
        }
        WHERE {
            SELECT ?entry
                   (?old_position - 1) AS ?position
            WHERE {
                ?entry a nfo:MediaFileListEntry ;
                         nfo:listPosition ?old_position .
                ?playlist nfo:hasMediaFileListEntry ?entry .
                FILTER (?old_position > ?removed_position)
                {
                    SELECT ?playlist
                           ?removed_position
                    WHERE {
                        ?playlist a nmm:Playlist ;
                                  a nfo:MediaList ;
                                    nfo:hasMediaFileListEntry
                                    ?removed_entry .
                        ?removed_entry nfo:listPosition ?removed_position .
                        FILTER (
                            tracker:id(?playlist) = %(playlist_id)s &&
                            tracker:id(?removed_entry) = %(entry_id)s
                        )
                    }
                }
            }
        };
        INSERT OR REPLACE {
            ?playlist nfo:entryCounter ?new_counter .
        }
        WHERE {
            SELECT ?playlist
                   (?counter - 1) AS ?new_counter
            WHERE {
                ?playlist a nmm:Playlist ;
                          a nfo:MediaList ;
                            nfo:entryCounter ?counter .
                FILTER (
                    tracker:id(?playlist) = %(playlist_id)s
                )
            }
        };
        DELETE {
            ?playlist nfo:hasMediaFileListEntry ?entry .
            ?entry a rdfs:Resource .
        }
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            FILTER (
                tracker:id(?playlist) = %(playlist_id)s &&
                tracker:id(?entry) = %(entry_id)s
            )
        }
        '.replace('
', ' ').strip() % {'playlist_id': self.props.pl_id, 'entry_id': media.get_id()}
        self._tracker.update_async(update_query, None, update_cb)
    song_id = coresong.props.media.get_id()
    entry_query = '
    SELECT
        %(media_type)s AS ?type
        ?entry AS ?id
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            ?entry a nfo:MediaFileListEntry ;
                     nfo:entryUrl ?url .
            SERVICE <dbus:%(miner_fs_busname)s> {
                GRAPH tracker:Audio {
                    SELECT
                        ?song
                        ?url
                    WHERE {
                        ?song a nmm:MusicPiece ;
                              nie:isStoredAs ?url .
                        FILTER (
                            %(filter_clause_song)s
                        )
                    }
                }
            }
            FILTER (
                %(filter_clause_pl)s
            )
        }
    '.replace('
', ' ').strip() % {'media_type': int(Grl.MediaType.AUDIO), 'filter_clause_song': 'tracker:id(?song) = ' + song_id, 'filter_clause_pl': 'tracker:id(?playlist) = ' + self.props.pl_id, 'miner_fs_busname': self._tracker_wrapper.props.miner_fs_busname}
    self._source.query(entry_query, [Grl.METADATA_KEY_ID], self._fast_options, entry_retrieved_cb)

