def save_correlation(self, subtype, obj_id, first_seen=None, last_seen=None):
    r_serv_metadata.zincrby('{}_all:{}'.format(self.correlation_name, subtype), obj_id, 0)
    if first_seen:
        r_serv_metadata.hset('{}_first_seen:{}'.format(self.correlation_name, subtype), obj_id, first_seen)
    if last_seen:
        r_serv_metadata.hset('{}_last_seen:{}'.format(self.correlation_name, subtype), obj_id, last_seen)

def save_correlation(self, subtype, obj_id, date):
    if not r_serv_metadata.exists('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id)):
        r_serv_metadata.hset('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id), 'first_seen', date)
        r_serv_metadata.hset('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id), 'last_seen', date)
    else:
        last_seen = r_serv_metadata.hget('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id), 'last_seen')
        if not last_seen:
            r_serv_metadata.hset('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id), 'last_seen', date)
        elif int(last_seen) < int(date):
            r_serv_metadata.hset('{}_metadata_{}:{}'.format(self.correlation_name, subtype, obj_id), 'last_seen', date)
    r_serv_metadata.zincrby('{}_all:{}'.format(self.correlation_name, subtype), obj_id, 0)

def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids_sorted = sorted(endoids, key=cmp_to_key(cmp_oids))
    new_columns = []
    for (fetchoid, column) in columns:
        if sorted(column, key=cmp_to_key(cmp_oid_pairs)) != column:
            column.sort(key=cmp_to_key(cmp_oid_pairs))
        i = 0
        new_column = []
        for (o, value) in column:
            eo = extract_end_oid(fetchoid, o)
            if len(column) != len(endoids_sorted):
                while i < len(endoids_sorted) and endoids_sorted[i] != eo:
                    new_column.append('')
                    i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids_sorted):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

