def decode_batch(self, window, location):
    n_samples = location.shape[0]
    for batch_id in range(n_samples):
        image_id = location[batch_id, 0]
        if image_id != self.current_id:
            if self.image_out is not None:
                self._save_image()
            self.current_id = image_id
            self.image_out = self._create_empty_image(window.shape)
        self.image_out[location[batch_id, 1]:location[batch_id, 1] + window.shape[0], location[batch_id, 2]:location[batch_id, 2] + window.shape[1]] = window
    return

def decode_batch(self, window, location):
    n_samples = location.shape[0]
    for batch_id in range(n_samples):
        image_id = location[batch_id, 0]
        if image_id != self.current_id:
            if self.image_out is not None:
                self._save_image()
            self.current_id = image_id
            self.image_out = self._create_empty_image(window.shape)
        self.image_out[batch_id] = window
    return

from ipaddress import IPv4Address, IPv4Interface
from typing import Optional

def get_interface_to_target(self, target: IPv4Address) -> Optional[IPv4Interface]:
    interfaces = network_interfaces()
    for interface in interfaces:
        if target in interface.network:
            return IPv4Interface(interface)
    return None

