    (controller_class, controller_kwargs) = select_device(arguments)
    controller = controller_class(**controller_kwargs)
    if arguments.command == 'version':
        version(controller)
    elif arguments.command == 'reset':
        reset(controller)
    elif arguments.command.startswith('write'):
        if arguments.command == 'write':
            if arguments.write_name:
                controller.write(name=arguments.write_name, value=arguments.write_value, event=arguments.write_event, bus=arguments.write_bus)
            elif arguments.write_id:
                if not arguments.write_data:
                    sys.exit('%s requires an id and data' % arguments.command)
                controller.write(id=arguments.write_id, data=arguments.write_data, bus=arguments.write_bus)
            elif arguments.write_input_file:
                write_file(controller, arguments.write_input_file)
            else:
                sys.exit('%s requires a signal name, message ID or filename' % arguments.command)
    else:
        print('Unrecognized command "%s"' % arguments.command)

def parse_options():
    parser = argparse.ArgumentParser(description='Send control messages to an attached OpenXC CAN translator', parents=[device_options()])
    parser.add_argument('command', type=str, choices=['version', 'reset', 'write'])
    write_group = parser.add_mutually_exclusive_group()
    write_group.add_argument('--name', action='store', dest='write_name', help='name for message write request')
    write_group.add_argument('--id', action='store', dest='write_id', help='ID for raw message write request')
    parser.add_argument('--value', action='store', dest='write_value', help='optional value for message write request')
    parser.add_argument('--event', action='store', dest='write_event', help='optional event for message write request')
    parser.add_argument('--data', action='store', dest='write_data', help='data for raw message write request')
    parser.add_argument('--bus', action='store', dest='write_bus', help='bus for message write request')
    write_group.add_argument('-f', '--file', action='store', dest='write_input_file', help='path to a file with a list of message requests')
    return parser.parse_args()

def list_certs(self, method='all'):
    ssl = self.client['Account']
    methods = {'all': 'getSecurityCertificates', 'expired': 'getExpiredSecurityCertificates', 'valid': 'getValidSecurityCertificates'}
    mask = 'mask[id, commonName, validityDays, notes]'
    func = getattr(ssl, methods[method])
    return func(mask=mask)

