def level_check(self):
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        self.consume_construction_material()
        self.level_up()
        self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.consume_construction_material()
        self.level_down()
        self._changed()

def level_check(self):
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        self.level_up()
        self.consume_construction_material()
        self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.level_down()
        self.consume_construction_material()
        self._changed()

    def consume_construction_material(self):
        amount_to_consume = 10
        self.inventory.alter(RES.CONSTRUCTION_MATERIAL_ID, -amount_to_consume)

