def run(self):
    if not Screenshot().have_pil():
        log.warning('Python Image Library is not installed, screenshots are disabled')
        return False
    img_counter = 0
    img_last = None
    while self.do_run:
        time.sleep(SHOT_DELAY)
        try:
            img_current = Screenshot().take()
        except IOError as e:
            log.error('Cannot take screenshot: %s', e)
            continue
        if img_last:
            if Screenshot().equal(img_last, img_current, SKIP_AREA):
                continue
        img_counter += 1
        try:
            tmpio = BytesIO()
            img_current.save(tmpio, format='JPEG')
            tmpio.seek(0)
            upload_to_host(tmpio, img_counter)
        except Exception as e:
            log.error('Failed to upload screenshot: %s', e)
        img_last = img_current
    return True

def upload_to_host(image_io, img_counter):
    nf = NetlogFile('shots/%s.jpg' % str(img_counter).rjust(4, '0'))
    try:
        nf.sock.sendall(image_io.getvalue())
    finally:
        nf.close()

