def worker(self) -> None:
    newversion = self.check_appcast()
    if newversion:
        status_widget = self.status_widgets.get(appname.lower())
        if status_widget:
            status_widget['text'] = newversion.title + ' is available'
        self.root.update_idletasks()

class Updater:

    def __init__(self, root):
        self.root = root
        self.status_widget = self.root.nametowidget('.{}.status'.format(appname.lower()))

    def worker(self) -> None:
        newversion = self.check_appcast()
        if newversion:
            self.status_widget['text'] = newversion.title + ' is available'
            self.root.update_idletasks()

async def get_backup_details(request):
    backup_id = request.match_info.get('backup_id', None)
    if not backup_id:
        raise web.HTTPBadRequest(reason='Backup id is required')
    else:
        try:
            backup_id = int(backup_id)
        except ValueError:
            raise web.HTTPBadRequest(reason='Invalid backup id')
    try:
        _resp = Backup.get_backup_details(id=backup_id)
        _resp['id'] = backup_id
        return web.json_response(_resp)
    except Backup.DoesNotExist:
        raise web.HTTPNotFound(reason='Backup with {} does not exist'.format(backup_id))

