import logging
from datetime import datetime

class EventWriter:

    def __init__(self, index_name, doc_type, flush_interval):
        self._index_name = index_name
        self._doc_type = doc_type
        self._flush_interval = flush_interval
        self._events = []
        self._counter = {u'events': 0}
        self._timing_start = datetime.now()
        logging.basicConfig(level=logging.INFO)

    def WriteEventBody(self, event_object):
        self._events.append({u'index': {u'_index': self._index_name, u'_type': self._doc_type}})
        self._events.append(self._GetSanitizedEventValues(event_object))
        self._counter[u'events'] += 1
        if self._counter[u'events'] % self._flush_interval == 0:
            self._FlushEventsToElasticsearch()
            timing_delta = datetime.now() - self._timing_start
            events_per_second = 0
            if timing_delta.seconds > 0:
                (events_per_second, _) = divmod(self._counter[u'events'], timing_delta.seconds)
            logging.info(u'Insert data: {0:d} events inserted (~{1:d} events/s)'.format(self._counter[u'events'], events_per_second))

    def _GetSanitizedEventValues(self, event_object):
        pass

    def _FlushEventsToElasticsearch(self):
        pass

