def aspirate(self, pipette_id: str, labware_id: str, well_name: str, well_location: WellLocation, volume: float) -> commands.AspirateResult:
    pipette_context = self.get_pipette_context(pipette_id)
    flow_rate = pipette_context.flow_rate
    request = commands.AspirateCreate(params=commands.AspirateParams(pipetteId=pipette_id, labwareId=labware_id, wellName=well_name, wellLocation=well_location, volume=volume, flowRate=flow_rate))
    result = self._transport.execute_command(request=request)
    return cast(commands.AspirateResult, result)

