def add_mapping_data(dp_id, clks):
    if not isinstance(clks, list) or not all((isinstance(clk, dict) for clk in clks)):
        raise ValueError('clks must be a list of dictionaries')
    if len(clks) == 0:
        raise ValueError('clks cannot be an empty list')
    receipt_token = generate_code()
    db.insert_raw_filter_data(get_db(), clks, dp_id, receipt_token)
    return receipt_token

def add_mapping_data(dp_id, clks):
    if not clks:
        raise ValueError('clks data cannot be empty')
    if not isinstance(clks, list):
        raise TypeError('clks data must be a list')
    receipt_token = generate_code()
    db.insert_raw_filter_data(get_db(), clks, dp_id, receipt_token)
    return receipt_token

def get_traffic_policy(self, policy_action_history):
    if self.endpoint_name in policy_action_history:
        history = policy_action_history[self.endpoint_name]
        if len(history):
            return history[-1]
    return None

