def fit_from_bb(self, image, bounding_box, gt_shape=None, **kwargs):
    algo_result = self.algorithm.run(image, bounding_box, gt_shape=gt_shape)
    return BasicResult(image, algo_result, gt_shape=gt_shape)

def fit_from_bb(self, image, bounding_box, gt_shape=None, **kwargs):
    algo_result = self.algorithm.run(image, bounding_box, gt_shape=gt_shape)
    return self._fitter_result(image, [algo_result], Affine.init_identity(2), gt_shape=gt_shape)

def _activate_mock(url, mock_response, method='GET'):
    if mock_response and _environment_supports_mocks():
        httpretty.enable()
        httpretty.register_uri(method, url, body=mock_response)
        yield
        httpretty.disable()
    else:
        yield

