def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        from scipy.sparse import coo_matrix
        coo = self.tocoo(copy=False)
        bsr_data = []
        bsr_indices = []
        bsr_indptr = [0]
        for i in range(coo.shape[0]):
            row_start = coo.indptr[i]
            row_end = coo.indptr[i + 1]
            for j in range(row_start, row_end):
                bsr_data.append(coo.data[j])
                bsr_indices.append(coo.indices[j])
            bsr_indptr.append(len(bsr_data))
        from bsr import bsr_matrix
        return bsr_matrix((bsr_data, bsr_indices, bsr_indptr), shape=self.shape, blocksize=blocksize, copy=copy)

def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        from scipy.sparse import coo_matrix
        coo = self.tocoo(copy=False)
        bsr_data = coo.data.reshape(-1, blocksize[0] * blocksize[1])
        bsr_indices = coo.row // blocksize[0]
        bsr_indptr = np.zeros(coo.shape[0] // blocksize[0] + 1, dtype=int)
        np.add.at(bsr_indptr, bsr_indices + 1, 1)
        bsr_indptr = np.cumsum(bsr_indptr)
        from bsr import bsr_matrix
        return bsr_matrix((bsr_data, bsr_indices, bsr_indptr), shape=(coo.shape[0] // blocksize[0], coo.shape[1]), copy=copy)

def new_path(road_map: MapInterface, trace: Trace, distance_epsilon: float, weight_time: str='minutes', weight_distance: str='meters') -> List[Road]:
    if len(trace.coords) < 1:
        return []
    origin = trace.coords[0]
    destination = trace.coords[-1]
    time_path = road_map.shortest_path(origin, destination, weight=weight_time)
    dist_path = road_map.shortest_path(origin, destination, weight=weight_distance)
    time_score = score(trace, time_path, distance_epsilon)
    dist_score = score(trace, dist_path, distance_epsilon)
    if dist_score > time_score:
        return dist_path
    else:
        return time_path

