def compute_output_spec(self, x, key):
    if isinstance(key, slice):
        if len(x.shape) == 0:
            raise ValueError(f'Too many indices for array: array is scalar but index {key} was requested. A scalar array cannot be indexed.')
        if x.shape[0] is not None and (key.start is not None and key.start >= x.shape[0]):
            raise ValueError(f'Array has shape {x.shape} but out-of-bound index {key.start} was requested.')
        if key.stop is not None and key.stop > x.shape[0]:
            raise ValueError(f'Array has shape {x.shape} but out-of-bound index {key.stop} was requested.')
    elif not isinstance(key, int):
        raise ValueError(f'Only scalar int keys or slices are supported at this time. Cannot process key {key}')
    if len(x.shape) == 0:
        raise ValueError(f'Too many indices for array: array is scalar but index {key} was requested. A scalar array cannot be indexed.')
    if x.shape[0] is not None and key >= x.shape[0]:
        raise ValueError(f'Array has shape {x.shape} but out-of-bound index {key} was requested.')
    return KerasTensor(x.shape[1:], dtype=x.dtype)

