def __init__(self, interface, proto, maxPacketSize=8192, reactor=None):
    if components.implements(proto, ethernet.IEthernetProtocol):
        self.ethernet = 1
    else:
        self.ethernet = 0
        if not components.implements(proto, ip.IIPProtocol):
            raise ValueError('The provided protocol does not implement IIPProtocol.')
    base.BasePort.__init__(self, reactor)
    self.interface = interface
    self.protocol = proto
    self.maxPacketSize = maxPacketSize
    self.setLogStr()

