import json
import logging

class ConfigManager:

    def __init__(self, config_file: str):
        self.config_file = config_file
        self.configs = self.load_configs()

    def load_configs(self):
        with open(self.config_file, 'r') as f:
            return json.load(f)

    def get_config(self, config_key: str):
        if config_key in self.configs:
            return self.configs[config_key]
        else:
            raise ValueError('Unknown config.')
config_manager = ConfigManager('configs.json')

def get_config(config_key: str):
    config = config_manager.get_config(config_key)
    logging.info('Loaded config %s', config_key)
    logging.info('Config output location : %s', config['output_dir'])
    return config

