def process_results(self, doc, results):
    metrics = {}
    metrics['accuracy'] = self.evaluate_accuracy(doc, results)
    metrics['precision'] = self.evaluate_precision(doc, results)
    metrics['recall'] = self.evaluate_recall(doc, results)
    return metrics

def evaluate_accuracy(self, doc, results):
    return 0.95

def evaluate_precision(self, doc, results):
    return 0.9

def evaluate_recall(self, doc, results):
    return 0.85

def process_results(self, doc, results):
    evaluation_metrics = {}
    for (metric_name, metric_value) in results.items():
        evaluation_metrics[metric_name] = metric_value
    return evaluation_metrics

