class InputHandler:

    def __init__(self, inputs):
        self.inputs = inputs
        self.index = 0

    def getch(self):
        if self.index < len(self.inputs):
            char = self.inputs[self.index]
            self.index += 1
            return char
        else:
            raise ValueError('No more characters provided in input')

