        if pipeline_host:
            setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
            setattr(self.parameters, 'source_pipeline_host', pipeline_host)

def maybe_adjust_fees(plugin: Plugin, scids: list):
    MAX_RATIO_THRESHOLD = 0.1
    for scid in scids:
        our = plugin.adj_balances[scid]['our']
        total = plugin.adj_balances[scid]['total']
        ratio = get_ratio(our / total)
        if ratio < MAX_RATIO_THRESHOLD:
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio), int(plugin.adj_ppmfee * ratio))
                plugin.log('Adjusted fees of {} with a ratio of {}'.format(scid, ratio))
            except RpcError as e:
                plugin.log('setchannelfee error: ' + str(e), level='warn')
        else:
            plugin.log('Skipped adjusting fees for {} due to high ratio of {}'.format(scid, ratio), level='warn')

def maybe_adjust_fees(plugin: Plugin, scids: list):
    THRESHOLD = 0.1
    for scid in scids:
        our = plugin.adj_balances[scid]['our']
        total = plugin.adj_balances[scid]['total']
        ratio = get_ratio(our / total)
        if ratio > THRESHOLD:
            try:
                plugin.rpc.setchannelfee(scid, int(plugin.adj_basefee * ratio), int(plugin.adj_ppmfee * ratio))
                plugin.log('Adjusted fees of {} with a ratio of {}'.format(scid, ratio))
            except RpcError as e:
                plugin.log('setchannelfee error: ' + str(e), level='warn')

def handler(request, path=None):
    if path is None:
        path = request.path
    page = Page.objects.page_for_path_or_404(path)
    if not page.are_ancestors_active():
        return HttpResponseNotFound('Page not found.')
    return build_page_response(page, request)

def handler(request, path=None):
    if path is None:
        path = request.path
    page = Page.objects.page_for_path_or_404(path)
    if not page.are_ancestors_active() or not page.is_active:
        return HttpResponseForbidden('Access to this page is forbidden.')
    return build_page_response(page, request)

def setChild(self, name, value):
    assert name == self.named_child, name
    if type(value) is list:
        value = tuple(value)
    if self.checker is not None:
        value = self.checker(value)
    if type(value) is tuple:
        for val in value:
            val.parent = self
    elif value is not None:
        value.parent = self
    attr_name = 'subnode_' + name
    old_value = getattr(self, attr_name)
    assert old_value is not value, value
    if old_value != value:
        if hasattr(self, 'debug') and self.debug:
            print(f'Changing {attr_name} from {old_value} to {value}')
    setattr(self, attr_name, value)

def setChild(self, name, value):
    assert name == self.named_child, name
    if type(value) is list:
        value = tuple(value)
    if self.checker is not None:
        value = self.checker(value)
    if type(value) is tuple:
        for val in value:
            val.parent = self
    elif value is not None:
        value.parent = self
    attr_name = 'subnode_' + name
    old_value = getattr(self, attr_name)
    if self.debug_mode:
        if old_value is value:
            print(f'Warning: Attempting to set {attr_name} to the same value.')
    assert old_value is not value, value
    setattr(self, attr_name, value)

def POST(self, req):
    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text
            yield key, version
    max_body_size = min(
        2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH,
        10 * 1024 * 1024)
    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()
        req.check_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)
        quiet = elem.find('./Quiet')
        if quiet is not None and quiet.text.lower() == 'true':
            self.quiet = True
        else:
            self.quiet = False
        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise
    elem = Element('DeleteResult')
    # check bucket existence
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)
    if any(version is not None for _key, version in delete_list):
        # Support deleting specific versions of objects
        for key, version in delete_list:
            if version:
                # Call the delete function with the version
                do_delete(req, key, version)
            else:
                # Call the delete function without a version
                do_delete(req, key, None)
    def do_delete(base_req, key, version):
        req = copy.copy(base_req)
        req.environ = copy.copy(base_req.environ)
        req.object_name = key
        try:
            query = req.gen_multipart_manifest_delete_query(self.app, version=version)
            resp = req.get_response(self.app, method='DELETE', query=query,
                                    headers={'Accept': 'application/json'})
            if query:
                try:
                    delete_result = json.loads(resp.body)
                    if delete_result['Errors']:
                        msg_parts = [delete_result['Response Status']]
                        msg_parts.extend(
                            '%s: %s' % (obj, status)
                            for obj, status in delete_result['Errors'])
                        return key, {'code': 'SLODeleteError',
                                     'message': '\n'.join(msg_parts)}
                except (ValueError, TypeError, KeyError):
                    self.logger.exception(
                        'Could not parse SLO delete response: %r',
                        resp.body)
                    return key, {'code': 'SLODeleteError',
                                 'message': 'Unexpected swift response'}
        except NoSuchKey:
            pass
        except ErrorResponse as e:
            return key, {'code': e.__class__.__name__, 'message': e._msg}
        return key, None
    with StreamingPile(self.conf.multi_delete_concurrency) as pile:
        for key, err in pile.asyncstarmap(do_delete, (
                (req, key, version) for key, version in delete_list))):
            if err:
                error = SubElement(elem, 'Error')
                SubElement(error, 'Key').text = key
                SubElement(error, 'Code').text = err['code']
                SubElement(error, 'Message').text = err['message']
            elif not self.quiet:
                deleted = SubElement(elem, 'Deleted')
                SubElement(deleted, 'Key').text = key
    body = tostring(elem)
    return HTTPOk(body=body)

def POST(self, req):
