import xml.sax.saxutils as saxutils

def setAuthors(template, authors):
    text = ''
    for (name, href) in authors:
        escaped_name = saxutils.escape(name)
        escaped_href = saxutils.quoteattr(href)
        anchor = f'<a href={escaped_href}>{escaped_name}</a>'
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','
    childNodes = microdom.parseString('<span>' + text + '</span>').childNodes
    for node in domhelpers.findElementsWithAttribute(template, 'class', 'authors'):
        node.childNodes.extend(childNodes)
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString(f'<link rel="author" href={escaped_href} title={escaped_name}/>').childNodes[0] for (name, href) in authors]
    head.childNodes.extend(authors)

from xml.sax.saxutils import escape

def setAuthors(template, authors):
    text = ''
    for (name, href) in authors:
        escaped_name = escape(name)
        escaped_href = escape(href)
        anchor = '<a href="%s">%s</a>' % (escaped_href, escaped_name)
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','
    childNodes = microdom.parseString('<span>' + text + '</span>').childNodes
    for node in domhelpers.findElementsWithAttribute(template, 'class', 'authors'):
        node.childNodes.extend(childNodes)
    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>' % (escaped_href, escaped_name)).childNodes[0] for (name, href) in authors]
    head.childNodes.extend(authors)

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        expr_str = purestr(expr)
        arg_strs = []
        for (i, arg) in enumerate(expr.args):
            arg_strs.append(purestr(arg) + '_%s' % str(pos + (i,)))
        if repeat:
            expr_str += '_%s' % str(pos)
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

def dotedges(expr, atom=lambda x: not isinstance(x, Basic), pos=(), repeat=True):
    if atom(expr):
        return []
    else:
        expr_str = purestr(expr)
        arg_strs = [purestr(arg) for arg in expr.args]
        if repeat:
            expr_str += '_%s' % str(pos)
            arg_strs = [arg_str + '_%s' % str(pos + (i,)) for (i, arg_str) in enumerate(arg_strs)]
        return ['"%s" -> "%s";' % (expr_str, arg_str) for arg_str in arg_strs]

def on_window_keypress_event(self, widget, event, user_data=None):
    if check_keypress(event, ['Control', 'f']):
        self.search_box.grab_focus()
        return True
    if check_keypress(event, ['Control', 's']):
        self.save_current_document()
        return True
    return False

def save_current_document(self):
    with open(self.current_file_path, 'w') as file:
        file.write(self.document_content)
    print('Document saved successfully.')

def on_window_keypress_event(self, widget, event, user_data=None):
    if check_keypress(event, ['Control', 'f']):
        self.search_box.grab_focus()
        return True
    if check_keypress(event, ['Control', 's']):
        self.save_launcher()
        return True
    return False

from typing import Optional

def lookup_class(kind: str, apiVersion: Optional[str]=None, default: Optional[str]=None) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None
    if klass:
        register_class(className, klass)
    return klass

from typing import Optional
_ClassRegistry = {}
_shortNameRegistry = {}

def lookup_class(kind: str, apiVersion: Optional[str]=None, default: Optional[str]=None) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className)
    except ImportError:
        klass = None
    if klass:
        register_class(className, klass)
    return klass

import pandas as pd

class Christmas:

    @staticmethod
    def observance(date):
        return date

class USNewYearsDay:

    @staticmethod
    def observance(date):
        return date

class GoodFriday:

    @staticmethod
    def _apply_rule(dt):
        return dt

def good_friday_unless_christmas_nye_friday(dts):
    years = dts.dt.year
    christmas_weekdays = Christmas.observance(pd.Timestamp(years, 12, 25)).weekday()
    nyd_weekdays = USNewYearsDay.observance(pd.Timestamp(years, 1, 1)).weekday()
    valid_days = (christmas_weekdays != 4) & (nyd_weekdays != 4)
    return GoodFriday._apply_rule(dts[valid_days]) if valid_days.any() else pd.NaT

import pandas as pd
from pandas.tseries.holiday import AbstractHolidayCalendar, GoodFriday
from .holidays_us import Christmas, USNewYearsDay

def good_friday_unless_christmas_nye_friday(dt):
    if isinstance(dt, pd.Series):
        return dt.apply(good_friday_unless_christmas_nye_friday)
    year = dt.year
    christmas_weekday = Christmas.observance(pd.Timestamp(year, 12, 25)).weekday()
    nyd_weekday = USNewYearsDay.observance(pd.Timestamp(year, 1, 1)).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        return pd.NaT

