def setkey(self, propname):
    if self.key:
        if propname == self.key:
            return
        old_key = self.key
        old_iv = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
        old_iv = old_iv.ordered(1)
        for row in self.getview():
            old_iv.remove(k=getattr(row, old_key), i=row.id)
    prop = self.properties.get(propname, None)
    if prop is None:
        prop = self.privateprops.get(propname, None)
    if prop is None:
        raise KeyError, "no property %s" % propname
    if not isinstance(prop, hyperdb.String):
        raise TypeError, "%s is not a String" % propname
    self.key = propname
    iv = self.db._db.view('_%s' % self.classname)
    if self.db.fastopen and iv.structure():
        return
    self.db.dirty = 1
    iv = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
    iv = iv.ordered(1)
    for row in self.getview():
        iv.append(k=getattr(row, propname), i=row.id)
    self.db.commit()

def setkey(self, propname):
    if self.key:
        if propname == self.key:
            return
        self.remove_key_from_index(self.key)
        raise ValueError, "%s already indexed on %s"%(self.classname, self.key)
    prop = self.properties.get(propname, None)
    if prop is None:
        prop = self.privateprops.get(propname, None)
    if prop is None:
        raise KeyError, "no property %s" % propname
    if not isinstance(prop, hyperdb.String):
        raise TypeError, "%s is not a String" % propname
    self.key = propname
    iv = self.db._db.view('_%s' % self.classname)
    if self.db.fastopen and iv.structure():
        return
    self.db.dirty = 1
    iv = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
    iv = iv.ordered(1)
    for row in self.getview():
        iv.append(k=getattr(row, propname), i=row.id)
    self.db.commit()
    self.add_key_to_index(propname)
