def __init__(self, model: openvino.runtime.Model, parent_model: OVBaseModel, ov_config: Optional[Dict[str, str]]=None, model_name: str='encoder', model_dir: str=None):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for (idx, key) in enumerate(self.model.inputs)}
    self.input_dtype = {inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()] for inputs in self.model.inputs}
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}
    if 'CACHE_DIR' not in self.ov_config:
        if 'tmp' in str(self._model_dir):
            pass
        else:
            self.ov_config['CACHE_DIR'] = os.path.join(self._model_dir, self._model_name)

def __init__(self, model: openvino.runtime.Model, parent_model: OVBaseModel, ov_config: Optional[Dict[str, str]]=None, model_name: str='encoder', model_dir: str=None):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for (idx, key) in enumerate(self.model.inputs)}
    self.input_dtype = {inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()] for inputs in self.model.inputs}
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}
    if 'CACHE_DIR' not in self.ov_config:
        if not self._model_dir.is_dir() or 'tmp' in str(self._model_dir):
            pass
        else:
            self.ov_config['CACHE_DIR'] = os.path.join(self._model_dir, self._model_name)

import os

def expand_path(path):
    return os.path.expanduser(path)

def validateTexturePath(path):
    path = expand_path(path)
    if not os.path.exists(path):
        raise FileNotFoundError(f'The path {path} does not exist.')
    return path

import os

class ValidationException(Exception):
    pass

def expand_path(path):
    return os.path.expanduser(path)

def validatePath(path):
    if not os.path.exists(path):
        raise ValidationException('%r does not exist' % path)
    if not os.path.isdir(path):
        raise ValidationException('%r is not a directory' % path)
    return os.path.abspath(path)

def validateTexturePath(path):
    path = expand_path(path)
    validatePath(path)
    return path

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create()
        for (key, value) in kwargs.items():
            setattr(project_update, key, value)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create()
        for (key, value) in kwargs.items():
            setattr(project_update, key, value)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def visit_ConstantNode(self, node):
    self.write(self.escape_value(node.value))

def escape_value(self, value):
    return str(value).replace("'", "'")

def visit_ConstantNode(self, node):
    escaped_value = self.escape_value(node.value)
    self.write("'" + escaped_value + "'")

    def escape_value(self, value):
        return str(value).replace("'", "''")

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        if not self.has_snapshot(entry, 'after_input'):
            self.take_snapshot(entry, 'after_input')

    def has_snapshot(self, entry, snapshot_type):
        return entry.snapshots.get(snapshot_type) is not None

    def take_snapshot(self, entry, snapshot_type):
        entry.take_snapshot(snapshot_type)

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        snapshot = entry.snapshots.get('after_input')
        if snapshot:
            continue
        entry.take_snapshot('after_input')

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        saved_object = self._saved
        self._saved = None
        return saved_object
    else:
        return self._generator.next()

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        saved_object = self._saved
        self._saved = None
        return saved_object
    else:
        return self._generator.next()

