def copy(self):
    self.temp_dir = tempfile.mkdtemp(suffix='', prefix='barman-')
    try:
        self._progress_init()
        _logger.info('Copy started (safe before %r)', self.safe_horizon)
        for item in self.item_list:
            if not item.is_directory:
                continue
            _logger.info(self._progress_message('analyze %s' % item))
            self._analyze_directory(item)
            _logger.info(self._progress_message('create destination directories and delete unknown files for %s' % item))
            self._create_dir_and_purge(item)
        pool = Pool(processes=self.workers, initializer=_init_worker, initargs=(self._execute_job,))
        for _ in pool.imap_unordered(_run_worker, self._job_generator()):
            pass
        for item in self.item_list:
            if isinstance(item, PGCONTROL_CLASS):
                _logger.info(self._progress_message('executing final step for %s' % item))
                self._execute_pgcontrol(item)
    except:
        _logger.info('Copy failed (safe before %s)', self.safe_horizon)
        raise
    else:
        _logger.info('Copy finished (safe before %s)', self.safe_horizon)
    finally:
        shutil.rmtree(self.temp_dir)
        self.temp_dir = None

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    filtered_asset_deps = {key: deps for (key, deps) in self._asset_deps.items() if key in selected_asset_keys}
    return AssetsDefinition(keys_by_input_name=self._keys_by_input_name, keys_by_output_name=self._keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=filtered_asset_deps, can_subset=self.can_subset, selected_asset_keys=selected_asset_keys & self.keys, resource_defs=self.resource_defs, group_names_by_key=self.group_names_by_key)

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    selected_asset_deps = {key: self.asset_deps[key] for key in selected_asset_keys if key in self.asset_deps}
    filtered_asset_keys = set(selected_asset_keys)
    for key in selected_asset_keys:
        filtered_asset_keys.update(selected_asset_deps.get(key, []))
    return AssetsDefinition(asset_keys_by_input_name=self._asset_keys_by_input_name, asset_keys_by_output_name=self._asset_keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=self._asset_deps, can_subset=self.can_subset, selected_asset_keys=filtered_asset_keys)

def update_tool(db: Session, tool: Tool, patch_tool: t.Union[CreateTool, PatchToolDockerimage]) -> Tool:
    if isinstance(patch_tool, CreateTool):
        tool.name = patch_tool.name
    elif patch_tool.persistent:
        tool.docker_image_template = patch_tool.persistent
        tool.is_read_only = True
    db.add(tool)
    db.commit()
    return tool

