                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

def __init__(self, database):
    self.database = database
    self.types = {lltype.Char: 'i8', lltype.Bool: 'i1', lltype.SingleFloat: 'float', lltype.Float: 'double', lltype.UniChar: 'i16', lltype.Void: 'void', lltype.UnsignedLongLong: 'i64', lltype.SignedLongLong: 'i64', llmemory.Address: 'i8*'}
    if sys.maxint == 2 ** 31 - 1:
        self.types.update({lltype.Signed: 'i32', lltype.Unsigned: 'i32'})
    elif sys.maxint == 2 ** 63 - 1:
        self.types.update({lltype.Signed: 'i64', lltype.Unsigned: 'i64'})
    else:
        raise Exception('Unsupported platform - unknown word size')
    self.reprs = {lltype.SignedLongLong: self.repr_signed, lltype.Signed: self.repr_signed, lltype.UnsignedLongLong: self.repr_default, lltype.Unsigned: self.repr_default, lltype.SingleFloat: self.repr_singlefloat, lltype.Float: self.repr_float, lltype.Char: self.repr_char, lltype.UniChar: self.repr_unichar, lltype.Bool: self.repr_bool, lltype.Void: self.repr_void, llmemory.Address: self.repr_address}
    try:
        import ctypes
    except ImportError:
        pass
    else:
        from pypy.rpython.rctypes import rcarithmetic as rcarith
        self.types.update({rcarith.CByte: self.types[lltype.Char], rcarith.CUByte: 'i8', rcarith.CShort: 'i16', rcarith.CUShort: 'i16', rcarith.CInt: 'i32', rcarith.CUInt: 'i32', rcarith.CLong: self.types[lltype.Signed], rcarith.CULong: self.types[lltype.Unsigned], rcarith.CLonglong: self.types[lltype.SignedLongLong], rcarith.CULonglong: self.types[lltype.UnsignedLongLong]})

def __init__(self, database):
    self.database = database
    self.types = {lltype.Char: 'i8', lltype.Bool: 'i1', lltype.SingleFloat: 'float', lltype.Float: 'double', lltype.UniChar: 'i16', lltype.Void: 'void', lltype.UnsignedLongLong: 'i64', lltype.SignedLongLong: 'i64', llmemory.Address: 'i8*'}
    if sys.maxint == 2 ** 31 - 1:
        self.types.update({lltype.Signed: 'i32', lltype.Unsigned: 'i32'})
    elif sys.maxint == 2 ** 63 - 1:
        self.types.update({lltype.Signed: 'i64', lltype.Unsigned: 'i64'})
    else:
        raise Exception('Unsupported platform - unknown word size')
    self.reprs = {lltype.SignedLongLong: self.repr_signed, lltype.Signed: self.repr_signed, lltype.UnsignedLongLong: self.repr_default, lltype.Unsigned: self.repr_default, lltype.SingleFloat: self.repr_singlefloat, lltype.Float: self.repr_float, lltype.Char: self.repr_char, lltype.UniChar: self.repr_unichar, lltype.Bool: self.repr_bool, lltype.Void: self.repr_void, llmemory.Address: self.repr_address}
    try:
        import ctypes
    except ImportError:
        pass
    else:
        from pypy.rpython.rctypes import rcarithmetic as rcarith

        def update(from_, type):
            if from_ not in self.types:
                self.types[from_] = type
            if from_ not in self.reprs:
                self.reprs[from_] = self.repr_default
        for (k, v) in [(rcarith.CByte, self.types[lltype.Char]), (rcarith.CUByte, 'i8'), (rcarith.CShort, 'i16'), (rcarith.CUShort, 'i16'), (rcarith.CInt, 'i32'), (rcarith.CUInt, 'i32'), (rcarith.CLong, self.types[lltype.Signed]), (rcarith.CULong, self.types[lltype.Unsigned]), (rcarith.CLonglong, self.types[lltype.SignedLongLong]), (rcarith.CULonglong, self.types[lltype.UnsignedLongLong])]:
            update(k, v)

def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            header = table.getColumnHeader(columnIndex)
            if header:
                desc = self._script.utilities.displayedText(header)
                if desc and len(desc):
                    text = desc
                    if args['mode'] == 'speech':
                        if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                            text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                    elif args['mode'] == 'braille':
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                    result.append(text)
    return result

def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            header = table.getColumnHeader(columnIndex)
            if header:
                desc = self._script.utilities.displayedText(header)
            else:
                desc = table.getColumnDescription(columnIndex)
            if desc and len(desc):
                text = desc
                if args['mode'] == 'speech':
                    if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                elif args['mode'] == 'braille':
                    text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                result.append(text)
    return result

class SequenceNotFoundError(Exception):
    pass

def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise SequenceNotFoundError(f'Error: No sequence with name "{name}" in saved sequences.')
    return sequence

def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise FileNotFoundError(f'Error: No sequence with name "{name}" in saved sequences.')
    return sequence

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = self.cluster.metadata.keyspaces['ks'].tables['test_table']
    else:
        raise NotImplementedError('Older versions are not supported.')
    params = table_metadata.options
    assert 'sstable_compression' in params, "Looking for 'sstable_compression', but could not find it."
    chunk_length = int(params['chunk_length_kb'])
    assert chunk_length == value, 'Expected chunk_length: %s.  We got: %s' % (value, chunk_length)

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = '<%s>' % ', '.join(self.templated_types) if self.templated_types else ''
    suffix = '%s %s%s %s %s' % (modifiers, self.type_name, syntax, templated_types, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

