import ast

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            source = ast.parse(inspect.getsource(module))
            for node in ast.walk(source):
                if isinstance(node, ast.FunctionDef) or isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and target.id == name:
                            return True
            return False
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

import ast

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            source = ast.get_source_segment(module.__code__, module)
            tree = ast.parse(source)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef) or isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and target.id == name:
                            return True
            return False
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def visit_Ac_Implied_Do(self, o, **kwargs):
    result = []
    for item in o:
        result.append(self.process_item(item, **kwargs))
    return result
    return self.visit_Base(o, **kwargs)

def visit_Ac_Implied_Do(self, o, **kwargs):
    elements = o.get_elements()
    implied_do_result = []
    for element in elements:
        implied_do_result.append(self.visit(element, **kwargs))
    return implied_do_result

def primary_key(self):
    from kart.working_copy import gpkg_adapter, other_adapter
    with self.engine.connect() as conn:
        if self.engine.dialect.name == 'sqlite':
            return gpkg_adapter.pk(conn, self.table)
        elif self.engine.dialect.name == 'other_db':
            return other_adapter.pk(conn, self.table)
        else:
            raise NotImplementedError('Database type not supported')

def primary_key(self):
    from kart.working_copy import db_adapter
    with self.engine.connect() as conn:
        if self.db_type == 'GPKG':
            return db_adapter.pk_gpkg(conn, self.table)
        elif self.db_type == 'SQLITE':
            return db_adapter.pk_sqlite(conn, self.table)
        elif self.db_type == 'POSTGRESQL':
            return db_adapter.pk_postgresql(conn, self.table)
        else:
            raise NotImplementedError(f'Primary key retrieval not implemented for {self.db_type}')

def test_run_qobj(self):
    try:
        simulator = qiskitsimulator.QISKitCppSimulator()
    except FileNotFoundError as fnferr:
        raise unittest.SkipTest('cannot find {} in path'.format(fnferr))
    result = simulator.run(self.q_job)
    expected2 = {'000 000': 18, '001 001': 15, '010 010': 13, '011 011': 11, '100 100': 10, '101 101': 10, '110 110': 12, '111 111': 11}
    actual_counts = result.get_counts('test_circuit2')
    for key in expected2.keys():
        self.assertAlmostEqual(actual_counts.get(key, 0), expected2[key], delta=2)
    self.assertEqual(set(actual_counts.keys()), set(expected2.keys()))

